#!/usr/bin/env python3
"""VR-10 mutation driver for T1 Rework7-A.

For each mutant: apply an exact textual mutation, assert the mutation really
landed, run the designated focused gate, record raw status and failure count,
restore the file from its byte backup, and assert the restore is byte-identical.
A mutation that does not land, or a restore that is not byte-identical, aborts
the whole battery.
"""
import hashlib
import pathlib
import subprocess
import sys

ROOT = pathlib.Path("/Users/vladmihaimiron/Documents/DebateAIRO/dialectical-engine")
SCRATCH = pathlib.Path("/tmp/t1r7")

TARGETS = {
    "registration": ROOT / "apps/api/src/registration.ts",
    "main": ROOT / "apps/api/src/main.ts",
    "policy": ROOT / "packages/register/src/auth-policy.ts",
}
BACKUPS = {
    "registration": SCRATCH / "registration.baseline.ts",
    "main": SCRATCH / "main.baseline.ts",
    "policy": SCRATCH / "auth-policy.baseline.ts",
}

UNIT = ["node_modules/.bin/vitest", "run", "tests/unit/registration.test.ts", "-t", "T1 rework7"]
ARCH = ["node_modules/.bin/vitest", "run", "tests/architecture/t1-argon2-worker-contract.test.ts",
        "-t", "rework7|shutdown drains|clamp-absorption"]

ACQUIRE_ORDER_OLD = """        releaseAdmission = this.acquireRegistrationAdmission(correlationId);
        const email = normalizeEmailForBlindIndex(input.email);
        const recoveryEmail = normalizeEmailForBlindIndex(input.recoveryEmail);
        const emailBlindIndex = createEmailBlindIndex(this.dependencies.blindIndexKey, email);
        const existing = await this.dependencies.repository.findAuditIdentityByBlindIndex(emailBlindIndex);
"""
ACQUIRE_ORDER_NEW = """        const email = normalizeEmailForBlindIndex(input.email);
        const recoveryEmail = normalizeEmailForBlindIndex(input.recoveryEmail);
        const emailBlindIndex = createEmailBlindIndex(this.dependencies.blindIndexKey, email);
        const existing = await this.dependencies.repository.findAuditIdentityByBlindIndex(emailBlindIndex);
        releaseAdmission = this.acquireRegistrationAdmission(correlationId);
"""

HOLD_OLD = """              try {
                // Register the hold in `pendingMailDispatches` FIRST, so a
                // shutdown drain can see the work, and only then hand the budget
                // back — without waiting out the reservation lease, which would
                // hold an admission slot for seconds against a request that no
                // longer exists.
                this.dispatchMailReservationHold(await activate());
              } finally {
                admission?.();
              }
"""
HOLD_RELEASE_EARLY = """              try {
                const granted = await activate();
                admission?.();
                this.dispatchMailReservationHold(granted);
              } finally {
                admission?.();
              }
"""
HOLD_RETAIN_THROUGH_LEASE = """              try {
                const granted = await activate();
                this.dispatchMailReservationHold(granted);
                await new Promise<void>((resolve) => setTimeout(resolve,
                  this.dependencies.policy.channel.registrationMailDispatchMinimumReservationMs));
              } finally {
                admission?.();
              }
"""

IDEMPOTENCE_OLD = """    let released = false;
    return () => {
      if (released) return;
      released = true;
      this.registrationAdmissionsHeld -= 1;
"""
IDEMPOTENCE_NEW = """    return () => {
      this.registrationAdmissionsHeld -= 1;
"""

EXCLUSIVE_OLD = '      if (admissionOwner === "local") releaseAdmission?.();'
EXCLUSIVE_NEW = "      releaseAdmission?.();"

PROVISION_OLD = """          }));
        } catch (provisionError) {
"""
PROVISION_NEW = """          }));
          releaseAdmission?.();
        } catch (provisionError) {
"""

TIMER_OLD = """        const index = this.waitingMailDispatches.indexOf(waiting);
        if (index < 0) return;
        this.waitingMailDispatches.splice(index, 1);
        this.signalMailCapacity(request.correlationId);
"""
TIMER_NEW = """        const index = this.waitingMailDispatches.indexOf(waiting);
        if (index < 0) return;
        this.signalMailCapacity(request.correlationId);
"""

SHUTDOWN_OLD = """  await registration.drainRegistrationAdmissions();
  await registration.drainMailDispatches();
"""
SHUTDOWN_NEW = """  await registration.drainMailDispatches();
  await registration.drainRegistrationAdmissions();
"""

MUTANTS = [
    ("M01-raise-the-103-cap", "registration", UNIT, [(
        """    if (this.registrationAdmissionsHeld
      >= this.dependencies.policy.channel.structuralMaximumConcurrentRegistrations) {""",
        """    if (this.registrationAdmissionsHeld
      >= this.dependencies.policy.channel.structuralMaximumConcurrentRegistrations + 1_000_000) {""",
    )]),
    ("M02-acquire-after-first-repository-await", "registration", UNIT,
     [(ACQUIRE_ORDER_OLD, ACQUIRE_ORDER_NEW)]),
    ("M03-release-at-commit", "registration", UNIT, [(PROVISION_OLD, PROVISION_NEW)]),
    ("M04-release-before-hold-registered", "registration", UNIT,
     [(HOLD_OLD, HOLD_RELEASE_EARLY)]),
    ("M05-retain-admission-through-the-reservation-hold", "registration", UNIT,
     [(HOLD_OLD, HOLD_RETAIN_THROUGH_LEASE)]),
    ("M06-owners-not-mutually-exclusive", "registration", UNIT,
     [(EXCLUSIVE_OLD, EXCLUSIVE_NEW)]),
    ("M07-release-non-idempotent-isolated", "registration", UNIT,
     [(IDEMPOTENCE_OLD, IDEMPOTENCE_NEW)]),
    ("M08-release-non-idempotent-with-two-owners", "registration", UNIT,
     [(IDEMPOTENCE_OLD, IDEMPOTENCE_NEW), (EXCLUSIVE_OLD, EXCLUSIVE_NEW)]),
    ("M09-18s-deadline-for-registration", "registration", UNIT, [(
        """          waitDeadlineMs:
            this.dependencies.policy.channel.registrationMailDispatchQueueWaitTimeoutMs""",
        """          waitDeadlineMs:
            this.dependencies.policy.channel.mailDispatchQueueWaitTimeoutMs""",
    )]),
    ("M10-28s-deadline-for-resend", "registration", UNIT, [(
        "    const activate = await this.reserveMailDispatchPermit({ correlationId });",
        "    const activate = await this.reserveMailDispatchPermit({ correlationId,\n"
        "      waitDeadlineMs: this.dependencies.policy.channel"
        ".registrationMailDispatchQueueWaitTimeoutMs });",
    )]),
    ("M11-timed-out-waiter-left-retained", "registration", UNIT, [(TIMER_OLD, TIMER_NEW)]),
